// App members: disabled controls retain parent-tracked explanatory tooltips.
HWND modelTooltip=nullptr;std::map<HWND,std::wstring> modelHintTexts;
void updateModelHints(bool create=false){if(create){modelTooltip=CreateWindowExW(WS_EX_TOPMOST,TOOLTIPS_CLASSW,nullptr,WS_POPUP|TTS_ALWAYSTIP|TTS_NOPREFIX,0,0,0,0,hwnd,nullptr,GetModuleHandle(nullptr),nullptr);if(!modelTooltip)return;SendMessageW(modelTooltip,TTM_SETMAXTIPWIDTH,0,int(400*dpi));}
 if(!modelTooltip)return;for(auto& f:fields){if(!modelLocked(store->settings,f.key))continue;if(IsWindowEnabled(f.hwnd))EnableWindow(f.hwnd,FALSE);auto& reason=modelHintTexts[f.hwnd];if(reason.empty())reason=L"선택한 모델의 필수 설정이거나 지원하지 않는 항목입니다. 모델을 변경하면 수정할 수 있습니다.";TOOLINFOW item{sizeof item};item.hwnd=hwnd;item.uId=(UINT_PTR)f.hwnd;item.uFlags=TTF_SUBCLASS;item.rect={LONG(f.rect.x*dpi),LONG(f.rect.y*dpi),LONG((f.rect.x+f.rect.w)*dpi),LONG((f.rect.y+f.rect.h)*dpi)};item.lpszText=reason.data();SendMessageW(modelTooltip,create?TTM_ADDTOOLW:TTM_NEWTOOLRECTW,0,(LPARAM)&item);}}
